var sb=new System.Text.StringBuilder();
foreach(var n in new[]{"Ground","HarborSea","ZoneGrounds"}){ var g=GameObject.Find(n); if(g==null) continue; sb.Append(n+" pos="+g.transform.position+" scale="+g.transform.lossyScale+" layer="+LayerMask.LayerToName(g.layer)+"\n"); var mr=g.GetComponent<MeshRenderer>(); if(mr!=null) sb.Append("  mat="+mr.sharedMaterial.name+" shader="+mr.sharedMaterial.shader.name+" color="+(mr.sharedMaterial.HasProperty("_BaseColor")?mr.sharedMaterial.GetColor("_BaseColor").ToString():"-")+" tex="+(mr.sharedMaterial.mainTexture!=null?mr.sharedMaterial.mainTexture.name:"-")+" bounds="+mr.bounds+"\n"); var mf=g.GetComponent<MeshFilter>(); if(mf!=null) sb.Append("  mesh="+mf.sharedMesh.name+"\n"); var col=g.GetComponent<Collider>(); if(col!=null) sb.Append("  col="+col.GetType().Name+" mat="+(col.sharedMaterial!=null?col.sharedMaterial.name:"none")+"\n"); foreach(Transform t in g.transform){ var r=t.GetComponent<Renderer>(); sb.Append("  child "+t.name+" pos="+t.position+" scale="+t.lossyScale+" rb="+(r!=null?r.bounds.ToString():"-")+"\n"); } }
var rs=UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None); var b=new Bounds(); bool f=true; foreach(var r in rs){ if(r.transform.position.y<-100) continue; if(f){b=r.bounds;f=false;} else b.Encapsulate(r.bounds);} sb.Append("renderer bounds min="+b.min+" max="+b.max+"\n");
var cam=Camera.main; sb.Append("cam far="+cam.farClipPlane+" clear="+cam.clearFlags+" bg="+cam.backgroundColor+" sky="+(RenderSettings.skybox!=null?RenderSettings.skybox.name:"none")+" fog="+RenderSettings.fog+"\n");
sb.Append("layers: "); for(int i=0;i<32;i++){var n=LayerMask.LayerToName(i); if(n!="") sb.Append(i+"="+n+" ");}
return sb.ToString();
